mapper.select:
SELECT r.id, r.name, r.category_id, r.type, r.description, r.image, r.location,
       r.total_count, r.status, r.audit_reason, r.create_time, r.update_time,
       c.name AS category_name
FROM `resource` r
LEFT JOIN `category` c ON r.category_id = c.id


        AND r.category_id = #{categoryId}


        AND r.type = #{type}


        AND (r.name LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))


        AND r.status = #{status}


ORDER BY r.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM `resource` r


        AND r.category_id = #{categoryId}


        AND r.type = #{type}


        AND (r.name LIKE CONCAT('%', #{keyword}, '%') OR r.description LIKE CONCAT('%', #{keyword}, '%'))


        AND r.status = #{status}

mapper.update:
UPDATE `resource`
name = #{name}, category_id = #{categoryId}, type = #{type}, description = #{description}, image = #{image}, location = #{location}, total_count = #{totalCount}, update_time = NOW()
WHERE id = #{id}
